import sys

def main():
    input = sys.stdin.readline
    n, m = map(int, input().split())
    a = [list(map(int, input().split())) for _ in range(n)]
    b = [list(map(int, input().split())) for _ in range(n)]

    # For each position, it is always optimal/necessary to place
    # the smaller value in one matrix and the larger in the other.
    # We can assume:
    # a[i][j] = min(original pair), b[i][j] = max(original pair)
    # Then we only need to check whether both matrices are increasing.
    for i in range(n):
        for j in range(m):
            if a[i][j] > b[i][j]:
                a[i][j], b[i][j] = b[i][j], a[i][j]

    for i in range(n):
        for j in range(m):
            if i > 0:
                if a[i][j] <= a[i - 1][j] or b[i][j] <= b[i - 1][j]:
                    print("Impossible")
                    return
            if j > 0:
                if a[i][j] <= a[i][j - 1] or b[i][j] <= b[i][j - 1]:
                    print("Impossible")
                    return

    print("Possible")

if __name__ == "__main__":
    main()
